-- DUMP DE LA BASE DE DONNEES - METAMIND
-- Livrable 14 - PostgreSQL
-- Structure et donnees de test alignees sur les entites JPA actuelles.

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

DROP TABLE IF EXISTS credit_movements CASCADE;
DROP TABLE IF EXISTS publications CASCADE;
DROP TABLE IF EXISTS users CASCADE;
DROP TABLE IF EXISTS institutions CASCADE;

CREATE TABLE institutions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  code VARCHAR(40) NOT NULL,
  name VARCHAR(160) NOT NULL,
  email_domain VARCHAR(120) NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  credit_balance INTEGER NOT NULL DEFAULT 0,
  CONSTRAINT pk_institutions PRIMARY KEY (id),
  CONSTRAINT uk_institutions_code UNIQUE (code),
  CONSTRAINT uk_institutions_email_domain UNIQUE (email_domain),
  CONSTRAINT ck_institutions_credit_balance CHECK (credit_balance >= 0),
  CONSTRAINT ck_institutions_code_not_blank CHECK (length(trim(code)) > 0),
  CONSTRAINT ck_institutions_name_not_blank CHECK (length(trim(name)) > 0)
);

CREATE TABLE users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  first_name VARCHAR(80) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  email VARCHAR(160) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(30) NOT NULL,
  status VARCHAR(30) NOT NULL DEFAULT 'ACTIF',
  institution_id BIGINT NOT NULL,
  CONSTRAINT pk_users PRIMARY KEY (id),
  CONSTRAINT uk_users_email UNIQUE (email),
  CONSTRAINT fk_users_institution FOREIGN KEY (institution_id) REFERENCES institutions(id) ON UPDATE CASCADE ON DELETE RESTRICT,
  CONSTRAINT ck_users_role CHECK (role IN ('BIBLIOTHECAIRE', 'ADMINISTRATEUR')),
  CONSTRAINT ck_users_status CHECK (status IN ('ACTIF', 'DESACTIVE')),
  CONSTRAINT ck_users_first_name_not_blank CHECK (length(trim(first_name)) > 0),
  CONSTRAINT ck_users_last_name_not_blank CHECK (length(trim(last_name)) > 0),
  CONSTRAINT ck_users_email_format CHECK (position('@' in email) > 1)
);

CREATE TABLE publications (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  title VARCHAR(220) NOT NULL,
  author VARCHAR(160) NOT NULL,
  publication_year INTEGER NOT NULL,
  status VARCHAR(30) NOT NULL,
  visibility VARCHAR(30) NOT NULL,
  keywords_text VARCHAR(500) NOT NULL DEFAULT '',
  institution_id BIGINT NOT NULL,
  CONSTRAINT pk_publications PRIMARY KEY (id),
  CONSTRAINT fk_publications_institution FOREIGN KEY (institution_id) REFERENCES institutions(id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT ck_publications_status CHECK (status IN ('EN_ATTENTE', 'EXTRACTION', 'A_VALIDER', 'PUBLIE', 'SUPPRIME')),
  CONSTRAINT ck_publications_visibility CHECK (visibility IN ('PUBLIC', 'INSTITUTION')),
  CONSTRAINT ck_publications_year CHECK (publication_year BETWEEN 1900 AND 2100),
  CONSTRAINT ck_publications_title_not_blank CHECK (length(trim(title)) > 0),
  CONSTRAINT ck_publications_author_not_blank CHECK (length(trim(author)) > 0)
);

CREATE TABLE credit_movements (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY,
  institution_id BIGINT NOT NULL,
  type VARCHAR(30) NOT NULL,
  amount INTEGER NOT NULL,
  balance_after INTEGER NOT NULL,
  description VARCHAR(220) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT pk_credit_movements PRIMARY KEY (id),
  CONSTRAINT fk_credit_movements_institution FOREIGN KEY (institution_id) REFERENCES institutions(id) ON UPDATE CASCADE ON DELETE CASCADE,
  CONSTRAINT ck_credit_movements_type CHECK (type IN ('ACHAT', 'CONSOMMATION')),
  CONSTRAINT ck_credit_movements_amount CHECK (amount <> 0),
  CONSTRAINT ck_credit_movements_balance_after CHECK (balance_after >= 0),
  CONSTRAINT ck_credit_movements_description_not_blank CHECK (length(trim(description)) > 0)
);

CREATE INDEX idx_users_institution_id ON users(institution_id);
CREATE INDEX idx_users_role_status ON users(role, status);
CREATE INDEX idx_publications_institution_id ON publications(institution_id);
CREATE INDEX idx_publications_status_visibility ON publications(status, visibility);
CREATE INDEX idx_publications_year ON publications(publication_year);
CREATE INDEX idx_credit_movements_institution_date ON credit_movements(institution_id, created_at);
CREATE INDEX idx_publications_search_text ON publications USING GIN (
  to_tsvector('simple', coalesce(title, '') || ' ' || coalesce(author, '') || ' ' || coalesce(keywords_text, ''))
);

-- Donnees de test : 100 lignes minimum par table.
-- Les emails utilisent le domaine reserve .example afin de ne pas reprendre de comptes reels.





ALTER TABLE institutions ALTER COLUMN id RESTART WITH 101;
ALTER TABLE users ALTER COLUMN id RESTART WITH 121;
ALTER TABLE publications ALTER COLUMN id RESTART WITH 151;
ALTER TABLE credit_movements ALTER COLUMN id RESTART WITH 101;

ANALYZE institutions;
ANALYZE users;
ANALYZE publications;
ANALYZE credit_movements;
